def split_words(text: str) -> list[str]:
    words: list[str] = []
    current: list[str] = []
    word_started = False
    i = 0
    n = len(text)

    while i < n:
        c = text[i]

        # Comment: '#' at word start (outside quotes)
        if c == '#' and not word_started:
            while i < n and text[i] != '\n':
                i += 1
            continue

        # Delimiters
        if c == ' ' or c == '\t' or c == '\n':
            if word_started:
                words.append(''.join(current))
                current = []
                word_started = False
            i += 1
            continue

        # Backslash outside quotes
        if c == '\\':
            if i + 1 >= n:
                raise ValueError("trailing backslash")
            nxt = text[i + 1]
            if nxt == '\n':
                i += 2
            else:
                current.append(nxt)
                word_started = True
                i += 2
            continue

        # Single quote
        if c == "'":
            word_started = True
            j = i + 1
            while j < n:
                if text[j] == "'":
                    break
                current.append(text[j])
                j += 1
            else:
                raise ValueError("unterminated single quote")
            i = j + 1
            continue

        # Double quote
        if c == '"':
            word_started = True
            i += 1
            while i < n:
                c2 = text[i]
                if c2 == '"':
                    i += 1
                    break
                if c2 == '\\':
                    if i + 1 >= n:
                        raise ValueError("trailing backslash")
                    nxt = text[i + 1]
                    if nxt in ('"', '\\', '$', '`'):
                        current.append(nxt)
                        i += 2
                    elif nxt == '\n':
                        i += 2
                    else:
                        current.append('\\')
                        current.append(nxt)
                        i += 2
                else:
                    current.append(c2)
                    i += 1
            else:
                raise ValueError("unterminated double quote")
            continue

        # Regular character
        current.append(c)
        word_started = True
        i += 1

    if word_started:
        words.append(''.join(current))

    return words
